from __future__ import annotations

from collections.abc import Callable
from datetime import UTC, datetime
from typing import Annotated

from fastapi import Depends, Header, Request
from fastapi.security import HTTPAuthorizationCredentials, HTTPBearer
from sqlalchemy import select

from app.api.external.errors import ExternalApiError
from app.api.external.rate_limit import ExternalApiRateLimiter
from app.auth.dependencies import DbSession
from app.auth.security import AUTH_SEED_ALPHABET, AUTH_SEED_LENGTH, hash_token
from app.models import ExternalApiClient, User

external_bearer = HTTPBearer(
    auto_error=False,
    scheme_name="ExternalApiKey",
    description="External client key generated by a WOS administrator.",
)


async def authenticate_external_client(
    request: Request,
    db: DbSession,
    credentials: Annotated[HTTPAuthorizationCredentials | None, Depends(external_bearer)] = None,
) -> ExternalApiClient:
    limiter = request.app.state.external_api_rate_limiter
    if not isinstance(limiter, ExternalApiRateLimiter):
        raise RuntimeError("external API rate limiter is unavailable")
    client_ip = request.client.host if request.client is not None else "unknown"
    retry_after = await limiter.consume(f"ip:{client_ip}")
    if retry_after is not None:
        raise ExternalApiError(429, "rate_limit_exceeded", "Rate limit exceeded", retry_after)
    if (
        credentials is None
        or credentials.scheme.lower() != "bearer"
        or not credentials.credentials.startswith("wos_live_")
    ):
        raise ExternalApiError(401, "invalid_api_key", "Invalid API key")
    raw_key = credentials.credentials
    client = await db.scalar(
        select(ExternalApiClient).where(ExternalApiClient.key_hash == hash_token(raw_key))
    )
    if client is None:
        raise ExternalApiError(401, "invalid_api_key", "Invalid API key")
    retry_after = await limiter.consume(f"client:{client.id}")
    if retry_after is not None:
        raise ExternalApiError(429, "rate_limit_exceeded", "Rate limit exceeded", retry_after)
    if not client.is_active or client.revoked_at is not None:
        raise ExternalApiError(401, "api_client_disabled", "API client is disabled")
    client.last_used_at = datetime.now(UTC)
    await db.commit()
    return client


def require_scope(scope: str) -> Callable[..., object]:
    async def dependency(
        client: Annotated[ExternalApiClient, Depends(authenticate_external_client)],
    ) -> ExternalApiClient:
        if scope not in client.scopes:
            raise ExternalApiError(403, "insufficient_scope", "Insufficient scope")
        return client

    return dependency


async def resolve_external_user(
    db: DbSession,
    seed: Annotated[str | None, Header(alias="X-WOS-User-Seed")] = None,
) -> User:
    if (
        seed is None
        or len(seed) != AUTH_SEED_LENGTH
        or any(character not in AUTH_SEED_ALPHABET for character in seed)
    ):
        raise ExternalApiError(401, "invalid_user_seed", "Invalid user credential")
    user = await db.scalar(select(User).where(User.auth_seed == seed))
    if user is None or user.deleted_at is not None:
        raise ExternalApiError(401, "invalid_user_seed", "Invalid user credential")
    if not user.is_active:
        raise ExternalApiError(403, "user_disabled", "User account is disabled")
    return user
